"""
Rope木 (動的文字列・列操作データ構造 / Dynamic Sequence Rope)
Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)

【概要・用途】
文字列や列に対する以下の操作を高速に処理する木構造:
- 結合 (concat / +): O(1)
- 任意インデックス参照: O(log N)
- 部分列切り出し (slice): O(log N)
- 挿入 (insert), 削除 (delete): O(log N)
"""

# https://github.com/ddfkit/acsampl/blob/main/rope.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
class Rope:
    def __init__(self,l=None,r=None,s=""):
        if l is None and r is None:
            self.l=self.r=None;self.s=s;self.w=len(s)
        else:
            self.l=l if l is not None else Rope();self.r=r if r is not None else Rope()
            self.s="";self.w=self.l.w+self.r.w
    def __len__(self):return self.w
    def concat(self,o):
        if not self.w:return o
        if not o.w:return self
        return Rope(self,o)
    def __add__(self,o):return self.concat(o)
    def __getitem__(self,idx):
        if isinstance(idx,slice):
            st,ed,stp=idx.indices(self.w)
            return self._sub(st,ed)
        if idx<0:idx+=self.w
        if not (0<=idx<self.w):raise IndexError
        if self.l is None:return self.s[idx]
        return self.l[idx] if idx<self.l.w else self.r[idx-self.l.w]
    def _sub(self,st,ed):
        if st>=ed or st>=self.w or ed<=0:return Rope()
        if st<=0 and ed>=self.w:return self
        if self.l is None:return Rope(s=self.s[st:ed])
        lw=self.l.w
        if ed<=lw:return self.l._sub(st,ed)
        if st>=lw:return self.r._sub(st-lw,ed-lw)
        return self.l._sub(st,lw).concat(self.r._sub(0,ed-lw))
    def to_str(self):
        if self.l is None:return self.s
        return self.l.to_str()+self.r.to_str()

if __name__ == "__main__":
    r1 = Rope(s="hello_")
    r2 = Rope(s="world")
    r = r1 + r2
    assert len(r) == 11
    assert r[0] == "h" and r[6] == "w"
    assert r.to_str() == "hello_world"
    sub = r[3:8]
    assert sub.to_str() == "lo_wo"
    print("rope.py: tests passed!")
